// =============================================================================
// 专业主题库（200 主题 / 10 分类）
// -----------------------------------------------------------------------------
// 数据结构：
//   id           唯一编号 (theme_001 ~ theme_200)
//   title        主题标题（中文）
//   category     所属分类（10 大类）
//   intensity    尺度：'light' 轻度 / 'medium' 中度 / 'heavy' 重度
//   multiRef     是否多参考图（支持多张女性参考图上传）
//   description  主题简述
//   scenario     场景设定（写实电影风、镜头语言、环境描述）
//   beat15s      15 秒模式 6 镜头分镜
//   beat30s      30 秒模式 9 镜头分镜
//   beat60s      60 秒模式 9 镜头分镜（节奏更慢、细节更丰富）
// =============================================================================

import { fillPosePlaceholders } from '../utils/poseSelector';

export type Intensity = 'light' | 'medium' | 'heavy';
export type ThemeCategory =
  | '纯展示露出'   // 1. 纯展示露出
  | '轻情色'       // 2. 轻情色
  | '纯性爱'       // 3. 纯性爱 (多姿势多场景)
  | '运动健身'     // 4. 运动健身
  | '角色扮演'     // 5. 角色扮演
  | '户外野战'     // 6. 户外野战
  | '多人派对'     // 7. 多人派对
  | '女同情欲'     // 8. 女同情欲
  | '魔幻奇幻'     // 9. 魔幻奇幻
  | '奇异猎奇'     // 10. 奇异猎奇
  | 'SM重口'        // 11. SM 重口
  | '强制凌辱';     // 12. 强制凌辱

export interface ThemeBeat {
  shotNumber: number;        // 1-9
  scene: string;             // 镜头描述
  prompt: string;            // 该镜头对应的视频提示词
}

export interface ThemeEntry {
  id: string;
  title: string;
  category: ThemeCategory;
  intensity: Intensity;
  multiRef: boolean;         // true=需要多张女性参考图
  description: string;
  scenario: string;
  beat15s: ThemeBeat[];      // 15s = 6 个镜头
  beat30s: ThemeBeat[];      // 30s = 9 个镜头
  beat60s: ThemeBeat[];      // 60s = 9 个镜头（节奏更慢更详细）
  /** 日式关键词标签（如日文搜索词、AV 风格标签等），为空时自动取分类默认标签 */
  japaneseKeywords?: string[];
}

