// 辅助函数
// ═══════════════════════════════════════════════════════════════════════════
export function 按分类筛选主题(分类?: ThemeCategory): ThemeEntry[] {
  if (!分类) return THEME_LIBRARY;
  return THEME_LIBRARY.filter((t) => t.category === 分类);
}

export function 按强度筛选主题(强度?: Intensity): ThemeEntry[] {
  if (!强度) return THEME_LIBRARY;
  return THEME_LIBRARY.filter((t) => t.intensity === 强度);
}

export function 随机抽取主题(数量: number, 分类?: ThemeCategory, 强度?: Intensity): ThemeEntry[] {
  const pool = THEME_LIBRARY.filter((t) =>
    (!分类 || t.category === 分类) && (!强度 || t.intensity === 强度)
  );
  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(数量, shuffled.length));
}

export function 根据时长生成分镜(主题: ThemeEntry, 时长: 15 | 30 | 60): ThemeBeat[] {
  const shotCount = 时长 === 15 ? 6 : 时长 === 60 ? 9 : 9;
  return 获取主题镜头(主题, shotCount);
}

/**
 * 智能主题元素提取
 * 从主题的 title / scenario / description 中解析出可填入分镜的具体元素：
 *   服装（cosplay 主题）：修女服 / 比基尼 / 护士服 / JK / 旗袍 ...
 *   场景（cosplay 主题）：教堂 / 泳池 / 健身房 / 卧室 ...
 *   道具（props）：皮鞭 / 手铐 / 蜡烛 / 圣经 ...
 *   氛围（atmosphere）：柔光暖色 / 暗黑红黑 / 霓虹 / 强光阴影 ...
 *
 * 设计动机：原 themeLibrary 中很多主题（如 theme_136 修女诱罪）的 scenario
 * 和 beat 分镜都写成了与主题无关的通用内容（"书房木椅旁"），用户反馈主题
 * 与分镜不一致。这里从主题标题反向推断应有的服装 + 场景，并据此重写分镜。
 */

interface 主题元素 {
  服装: string;        // 例："黑色修女服配白色头巾和十字架项链"
  场景: string;        // 例："教堂内部，长椅、彩色玻璃窗、烛光"
  道具: string;        // 例："手持圣经和十字架念珠"，空字符串表示无道具
  氛围: string;        // 例："暖色调烛光与彩色玻璃光影"
  主体描述: string;    // 例："<Picture 1>"
  男性服装: string;    // 例："身穿黑色长袍配白色祭披和十字架的神父"
}

