/** 从主题文本中匹配关键词，返回首个匹配项的 value，否则 fallback */
function 匹配关键词(text: string, 词库: Array<[RegExp, string]>, fallback: string): string {
  for (const [regex, value] of 词库) {
    if (regex.test(text)) return value;
  }
  return fallback;
}

