/** 提取主题元素。优先用 title，回退到 scenario，再回退到 description */
function 提取主题元素(主题: ThemeEntry): 主题元素 & { 男性服装: string } {
  const titleText = 主题.title;
  const fullText = `${主题.title} ${主题.scenario} ${主题.description}`;

  // 服装：标题中包含 cosplay/服装词时优先使用标题匹配
  const 服装 = 匹配关键词(titleText, 服装关键词库, 匹配关键词(主题.scenario, 服装关键词库, '紧身日常服装连体搭配'));

  // 场景：优先使用"服装→标准场景"映射
  const 服装对应场景_ = 匹配关键词(titleText, 服装对应场景, '');
  const 场景 = 服装对应场景_ || 匹配关键词(主题.scenario, 场景关键词库, '私密空间');

  // 道具：可能多个匹配
  const 道具列表: string[] = [];
  for (const [regex, value] of 道具关键词库) {
    if (regex.test(fullText) && !道具列表.includes(value)) {
      道具列表.push(value);
      if (道具列表.length >= 2) break;
    }
  }
  const 道具 = 道具列表.join('，') || '';

  // 氛围
  const 氛围 = 匹配关键词(主题.scenario, 氛围关键词库, '电影级光影氛围');

  // 男性服装：根据主题类别匹配，让男性角色有合适的服装代入。
  // 之前固定 fallback 成"身穿深色西装的男性"导致所有未匹配关键词的主题
  // 男性都是西装，看起来千篇一律（用户反馈）。
  // 现在：标题/场景/描述都不匹配时，按主题 ID 哈希在 15 种多样化服装池中选一个。
  const 男性服装 = 匹配关键词(titleText, 男性服装对应场景, 匹配关键词(fullText, 男性服装关键词库, ''))
    || 选默认男性服装(主题);

  return {
    服装,
    场景,
    道具,
    氛围,
    主体描述: '<Picture 1>',
    男性服装,
  };
}

